// Build workflows/lsf-implement.js from the modules in this directory. The
// Workflow tool's script cannot import, so the modules are inlined: import
// and export statements are stripped and the files concatenated after the
// `meta` literal. Run: `node workflows/lsf/build.js`. test/build.test.js
// fails when the generated file is stale.

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const OUTPUT = resolve(here, '..', 'lsf-implement.js');
const MODULES = ['schema.js', 'graph.js', 'scheduling.js', 'implement.js'];

const META = `export const meta = {
  name: 'lsf-implement',
  description: 'Phase 3 of phronithm:large-scale-feature: wave loop over a decomposition plan — plan, critique, implement, review, merge, re-plan — stopping on structural signals and adjudicated architecture invalidation',
  whenToUse: 'After lsf-architecture has committed a decomposition plan. Pass args { name, planSha, architectureDoc, integrationBranch, ... }; see the header comment in workflows/lsf/implement.js.',
  phases: [
    { title: 'Load', detail: 'decision log, plan graph, validation' },
    { title: 'Units', detail: 'per unit: plan, critique, implement, review, completion report' },
    { title: 'Merge', detail: 'unit branches into the integration branch, plan order; merged worktrees removed' },
    { title: 'Gate', detail: 'does the wave invalidate the architecture document' },
    { title: 'Re-plan', detail: 'breakdown re-plan mode over the wave\\'s completion reports' },
    { title: 'Ledger', detail: 'signal ledger scribe' },
    { title: 'Termination', detail: 'meta-tasks and standing obligations' },
  ],
}
`;

function strip(source) {
  return source
    .replace(/^import\s[\s\S]*?from\s+'[^']+';\s*$/gm, '')
    .replace(/^export\s*\{[\s\S]*?\};\s*$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function build() {
  const parts = [META, '// GENERATED by workflows/lsf/build.js — edit the modules in workflows/lsf/, not this file.'];
  for (const m of MODULES) {
    parts.push(`// ---- inlined from workflows/lsf/${m}`);
    parts.push(strip(readFileSync(join(here, m), 'utf8')));
  }
  parts.push('return await run({ agent, parallel, log, args });');
  return parts.join('\n\n') + '\n';
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeFileSync(OUTPUT, build());
  console.log(`wrote ${OUTPUT}`);
}

export { build, strip, OUTPUT, META };
